import{_ as e,o as p,c as l,a3 as r}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"附录 常见的优先级结构设计","description":"","frontmatter":{"translationSource":{"title":"附录 常见的优先级结构设计","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=IlngKiLhDJAlZSX3Qv1eGF","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/appendix-common-priority-structures"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/appendix-common-priority-structures"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/appendix-common-priority-structures"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/appendix-common-priority-structures"}]]},"headers":[],"relativePath":"zh/appendix-common-priority-structures.md","filePath":"zh/page-IlngKiLhDJAlZSX3Qv1eGF.md"}'),i={name:"zh/appendix-common-priority-structures.md"};function s(t,a,o,n,c,d){return p(),l("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="附录-常见的优先级结构设计" tabindex="-1">附录 常见的优先级结构设计 <a class="header-anchor" href="#附录-常见的优先级结构设计" aria-label="Permalink to &quot;附录 常见的优先级结构设计&quot;">​</a></h1><blockquote><p>源页面 ID：<code>IlngKiLhDJAlZSX3Qv1eGF</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=IlngKiLhDJAlZSX3Qv1eGF" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-sNZTojqUdxbXh5mI6F3Lp9"></span></p><h4 id="常见的优先级结构" tabindex="-1">常见的优先级结构 <a class="header-anchor" href="#常见的优先级结构" aria-label="Permalink to &quot;常见的优先级结构&quot;">​</a></h4><p>除了箱子出口放汇流器形成的优先级之外，还有其他的一些结构也会产生优先级：</p><ol><li><p><span class="mark-purple">反应池中，</span><span class="mark-purple"><strong>输入物料优先输出，反应中生成的液化息壤优先反应，其他优先输出</strong></span><span class="mark-purple">；</span></p></li><li><p><span class="mark-purple">分流器指向汇流器时，</span><span class="mark-purple"><strong>后连接汇流器的线路优先级低</strong></span><span class="mark-purple">；</span></p></li><li><p><span class="mark-purple">取货口、反应池甚至取货口等容器出口放置汇流器时，</span><span class="mark-purple"><strong>容器输出优先级低于过路的传送带</strong></span><span class="mark-purple">。但是这个并不总是成立，暗管出口、储液罐就没有这一特性。此外，可以使用断电反应池作为分流器指汇流器的下位替代。</span></p></li><li></li></ol><blockquote><p><a href="/endfield-skydoc/zh/input-output-merge-priority-theory">优先输入/输出/汇入理论简要说明</a></p></blockquote><p><span id="source-block-H0ozGwHnWV5wiu8Ejp9HGN"></span></p><h4 id="大流量的优先输出结构" tabindex="-1">大流量的优先输出结构 <a class="header-anchor" href="#大流量的优先输出结构" aria-label="Permalink to &quot;大流量的优先输出结构&quot;">​</a></h4><p>由于传送带速度限制，当我们需要对流量大于30/m的固体或120/m的流体做优先输出时，最严格的方案需要将其分流到多条传送带/水管上，每条独立做一个如前所述的优先级，然后再各自汇流。但是，这样做并不是很方便，一般来说会考虑以下一些替代方案：</p><ol><li><p>使用分流结构替代优先输出（见2.4节等，不在本节讨论范围）</p></li><li><p>使用流体替代固体，例如对120赤铜气做优先级，等价于对240固体赤铜块做优先级（前提是这240赤铜块都会变成气体）</p></li><li><p>只对部分流量作优先级（本质仍与用分流类似，但具有优先级结构，因此放在这里说）</p></li></ol><p>下面是一些例子。</p><details><summary>使用存储箱控制30-60的固体流量优先级</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3cc3864874cd487e.q90-757e0cc6ecb3b760.webp" alt="附录 常见的优先级结构设计"></p><p>图中，我们计算得到平衡生产时，分离芯-铜罐一路的铜块的消耗量约为46，且需要优先分配。我们采用两路铜进入储存箱，两路直连塑形机，低优先级支路连接粉碎机-反应池实现。在这一设计下，当塑形机没有阻塞时，两路铜块会优先供应塑形机，没有铜块去往粉碎机。由此，分离芯在阻塞后，会将信号一路往回传播到塑形机的铜块。当铜块堆满时，30的流量分往粉碎机，而另外30的流量则留在储存箱中。分离芯消耗掉之后，铜块又会优先供应塑形机生产。</p><p>可以思考如下问题：等我有空了再回来写答案。</p><ol><li><p>如果对一条路做优先级控制，另一条路直接连塑形机，会发生什么情况，为什么不对？</p></li><li><p>储存箱子为什么需要关闭？</p></li><li><p>即使塑形机没有堵塞，为什么也还是会有一些铜漏到粉碎机？它有影响吗？（提示：从相位角度思考）</p></li></ol></details><p>更多例子可参考</p><p><a href="/endfield-skydoc/zh/625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy">625挡可调自适应小龙泡泡+重息壤配平玩具</a></p></div>',1)])])}const m=e(i,[["render",s]]);export{u as __pageData,m as default};
